namespace Solution.Api.Models;

public enum TableStatus { Free, Occupied, PartiallyPaid, Paid }
public enum OrderStatus { Open, PartiallyPaid, Paid, Cancelled }
public enum OrderItemStatus { Ordered, Served, Paid, Cancelled }
public enum PaymentStatus { Completed, Cancelled }

public sealed class Waiter { public int Id { get; set; } public string FirstName { get; set; } = string.Empty; public string LastName { get; set; } = string.Empty; public string Code { get; set; } = string.Empty; public bool IsActive { get; set; } = true; }
public sealed class MenuCategory { public int Id { get; set; } public string Name { get; set; } = string.Empty; public string Description { get; set; } = string.Empty; public int DisplayOrder { get; set; } public bool IsActive { get; set; } = true; }
public sealed class MenuItem { public int Id { get; set; } public int CategoryId { get; set; } public string Name { get; set; } = string.Empty; public string Description { get; set; } = string.Empty; public decimal Price { get; set; } public bool IsAvailable { get; set; } = true; public string? ImageUrl { get; set; } public MenuCategory? Category { get; set; } }
public sealed class PaymentMethod { public int Id { get; set; } public string Name { get; set; } = string.Empty; public bool IsActive { get; set; } = true; }
public sealed class RestaurantTable { public int Id { get; set; } public int Number { get; set; } public int Seats { get; set; } public string Zone { get; set; } = string.Empty; public TableStatus Status { get; set; } = TableStatus.Free; public int? WaiterId { get; set; } public int? OrderId { get; set; } public Waiter? Waiter { get; set; } }
public sealed class Order { public int Id { get; set; } public int TableId { get; set; } public int WaiterId { get; set; } public string OpenedAt { get; set; } = string.Empty; public OrderStatus Status { get; set; } = OrderStatus.Open; public string? ClosedAt { get; set; } public string? Notes { get; set; } public RestaurantTable? Table { get; set; } public Waiter? Waiter { get; set; } }
public sealed class OrderItem { public int Id { get; set; } public int OrderId { get; set; } public int MenuItemId { get; set; } public int Quantity { get; set; } public decimal UnitPrice { get; set; } public OrderItemStatus Status { get; set; } = OrderItemStatus.Ordered; public int? PaymentId { get; set; } public string? Notes { get; set; } public Order? Order { get; set; } public MenuItem? MenuItem { get; set; } public decimal Total => Quantity * UnitPrice; public bool IsPaid => PaymentId.HasValue || Status == OrderItemStatus.Paid; }
public sealed class Payment { public int Id { get; set; } public int OrderId { get; set; } public int PaymentMethodId { get; set; } public decimal Amount { get; set; } public decimal TipAmount { get; set; } public string PaidAt { get; set; } = string.Empty; public PaymentStatus Status { get; set; } = PaymentStatus.Completed; public Order? Order { get; set; } public PaymentMethod? PaymentMethod { get; set; } }
